  gap: 16px;
}

.movie-card {
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 16px;
}

.movie-card__title {
  font-size: 1.25rem;
  font-weight: 600;
}

.movie-card__screenings {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 12px;
