  width: min(100%, 40rem);
  border-radius: 4px;
}

.seat-map {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: fit-content;
  margin: 0 auto;
}

.seat-row {
  display: grid;
  grid-template-columns:
    $label-width repeat(4, $seat-width) $aisle-width repeat(16, $seat-width) $aisle-width repeat(4, $seat-width)
    $label-width;
  align-items: center;
  height: $row-height;
}

.row-label {
  text-align: center;
  font-size: 0.85rem;
  color: #555;
}

.aisle {
  height: 100%;
}

.seat,
.couch {
  height: calc(#{$row-height} - 4px);
  border: none;
  border-radius: 4px;
  color: #fff;
  font-size: 0.7rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  margin: 0 1px;
}

.seat:disabled,
.couch:disabled {
  cursor: not-allowed;
}

.legend {
  display: flex;
  gap: 24px;
  justify-content: center;
