import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { fetchMovie, fetchScreening } from '../../api/client';
import { Movie, Screening } from '../../api/types';
import { useBooking } from '../../booking/BookingContext';
import { formatPrice, priceForItem } from '../../utils/pricing';
import { groupSeatIds, seatIdsForItem, SelectionItem } from '../../utils/seats';
import './SummaryPage.scss';

export function SummaryPage() {
  const { id } = useParams();
  const screeningId = Number(id);
  const navigate = useNavigate();
  const { booking, setSeats } = useBooking();

  const [screening, setScreening] = useState<Screening | null>(null);
  const [movie, setMovie] = useState<Movie | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetchScreening(screeningId)
      .then(async (scr) => {
        const mov = await fetchMovie(scr.movieId);
        if (cancelled) return;
        setScreening(scr);
        setMovie(mov);
      })
      .catch(() => {
        if (!cancelled) navigate('/', { replace: true });
      });
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [screeningId]);

  if (!screening || !movie || !booking) return null;

  const items = groupSeatIds(booking.seats);
  const total = items.reduce((sum, item) => sum + priceForItem(item), 0);

  function handleRemove(item: SelectionItem) {
    const idsToRemove = new Set(seatIdsForItem(item));
    const next = booking!.seats.filter((seatId) => !idsToRemove.has(seatId));
    setSeats(next);
    if (next.length === 0) navigate(`/screenings/${screeningId}/seats`);
  }

  return (
    <div className="summary-page">
      <h1 data-testid="summary-title">Your tickets</h1>
      <div className="summary-list" data-testid="summary-list">
        {items.map((item) => (
          <div key={seatIdsForItem(item).join('-')} className="summary-item" data-testid="summary-item">
            <span data-testid="summary-item-title">{movie.title}</span>
            <span data-testid="summary-item-datetime">
              {screening.date} {screening.time}
            </span>
            <span data-testid="summary-item-row">{item.row}</span>
            <span data-testid="summary-item-seat">
              {item.kind === 'seat' ? item.column : `Couch ${item.columnStart}-${item.columnEnd}`}
            </span>
            <span data-testid="summary-item-price">{formatPrice(priceForItem(item))}</span>
            <Button data-testid="summary-item-remove-button" onClick={() => handleRemove(item)}>
              Remove
            </Button>
          </div>
        ))}
      </div>
      <div data-testid="summary-total" className="summary-total">
        Total: {total.toFixed(2)} PLN
      </div>
      <div className="summary-page__actions">
        <Button data-testid="back-button" variant="outlined" onClick={() => navigate(`/screenings/${screeningId}/seats`)}>
          Back
        </Button>
        <Button
          data-testid="confirm-button"
          variant="contained"
          onClick={() => navigate(`/screenings/${screeningId}/checkout`)}
        >
          Confirm
        </Button>
      </div>
    </div>
  );
}

export default SummaryPage;

import { CheckoutFormValues } from '../../booking/BookingContext';

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE_REGEX = /^\d{9}$/;

export type CheckoutErrors = Partial<Record<keyof CheckoutFormValues, string>>;

export function validateCheckoutForm(form: CheckoutFormValues): CheckoutErrors {
  const errors: CheckoutErrors = {};

  if (form.firstName === '') errors.firstName = 'First name is required';
  else if (form.firstName.length < 2) errors.firstName = 'First name must be at least 2 characters';

  if (form.lastName === '') errors.lastName = 'Last name is required';
  else if (form.lastName.length < 2) errors.lastName = 'Last name must be at least 2 characters';

  if (form.email === '') errors.email = 'Email is required';
  else if (!EMAIL_REGEX.test(form.email)) errors.email = 'Enter a valid email address';

  if (form.confirmEmail === '') errors.confirmEmail = 'Confirm email is required';
  else if (form.confirmEmail !== form.email) errors.confirmEmail = 'Email addresses do not match';

  if (form.phone !== '' && !PHONE_REGEX.test(form.phone)) {
    errors.phone = 'Phone number must be exactly 9 digits';
  }

  if (!form.terms) errors.terms = 'You must accept the terms and conditions';

  return errors;
}

.checkout-page {
  max-width: 600px;
  margin: 0 auto;
  padding: 24px;
}

.checkout-page__field {
  margin-bottom: 16px;
}

.checkout-page__error {
  color: #c62828;
  font-size: 0.8rem;
  margin-top: 4px;
}

.checkout-page__actions {
  display: flex;
  gap: 16px;
  margin-top: 24px;
}

import Button from '@mui/material/Button';
import Checkbox from '@mui/material/Checkbox';
import FormControlLabel from '@mui/material/FormControlLabel';
import TextField from '@mui/material/TextField';
import { useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { createReservation } from '../../api/client';
import { useBooking } from '../../booking/BookingContext';
import { useToast } from '../../toast/ToastContext';
import { priceForItem } from '../../utils/pricing';
import { flattenItemsToIds, groupSeatIds } from '../../utils/seats';
import { validateCheckoutForm } from './validation';
import './CheckoutPage.scss';

interface Touched {
  firstName: boolean;
  lastName: boolean;
  email: boolean;
  confirmEmail: boolean;
  phone: boolean;
  terms: boolean;
}

const NO_TOUCHED: Touched = {
  firstName: false,
  lastName: false,
  email: false,
  confirmEmail: false,
  phone: false,
  terms: false,
};

const ALL_TOUCHED: Touched = {
  firstName: true,
  lastName: true,
  email: true,
  confirmEmail: true,
  phone: true,
  terms: true,
};

export function CheckoutPage() {
  const { id } = useParams();
  const screeningId = Number(id);
  const navigate = useNavigate();
  const { booking, updateForm, markPaid } = useBooking();
  const { showToast } = useToast();

  const [touched, setTouched] = useState<Touched>(NO_TOUCHED);
  const [submitting, setSubmitting] = useState(false);

  if (!booking) return null;

  const form = booking.form;
  const errors = validateCheckoutForm(form);
  const items = groupSeatIds(booking.seats);
  const total = items.reduce((sum, item) => sum + priceForItem(item), 0);

  function blurField(field: keyof Touched) {
    setTouched((prev) => ({ ...prev, [field]: true }));
  }

  function handlePay() {
    const currentErrors = validateCheckoutForm(form);
    if (Object.keys(currentErrors).length > 0) {
      setTouched(ALL_TOUCHED);
      showToast('The form contains errors');
      return;
    }

    setSubmitting(true);
    createReservation({
      screeningId,
      seats: flattenItemsToIds(items),
      customer: {
        firstName: form.firstName,
        lastName: form.lastName,
        email: form.email,
        phone: form.phone,
      },
      totalPrice: total,
    })
      .then(() => {
        markPaid(form.email);
        navigate('/confirmation');
      })
      .catch(() => {
        setSubmitting(false);
        showToast('Payment failed. Please try again.');
      });
  }

  return (
    <div className="checkout-page">
      <h1 data-testid="checkout-title">Your details</h1>

      <div className="checkout-page__field">
        <TextField
          fullWidth
          data-testid="first-name-input"
          label={<span data-testid="first-name-label">First name *</span>}
          value={form.firstName}
          onChange={(e) => updateForm({ firstName: e.target.value })}
          onBlur={() => blurField('firstName')}
          error={touched.firstName && !!errors.firstName}
        />
        {touched.firstName && errors.firstName && (
          <div className="checkout-page__error" data-testid="first-name-error">
            {errors.firstName}
          </div>
        )}
      </div>

      <div className="checkout-page__field">
        <TextField
          fullWidth
          data-testid="last-name-input"
          label={<span data-testid="last-name-label">Last name *</span>}
          value={form.lastName}
          onChange={(e) => updateForm({ lastName: e.target.value })}
          onBlur={() => blurField('lastName')}
          error={touched.lastName && !!errors.lastName}
        />
        {touched.lastName && errors.lastName && (
          <div className="checkout-page__error" data-testid="last-name-error">
            {errors.lastName}
          </div>
        )}
      </div>

      <div className="checkout-page__field">
        <TextField
          fullWidth
          data-testid="email-input"
          label={<span data-testid="email-label">Email *</span>}
          value={form.email}
          onChange={(e) => updateForm({ email: e.target.value })}
          onBlur={() => blurField('email')}
          error={touched.email && !!errors.email}
        />
        {touched.email && errors.email && (
          <div className="checkout-page__error" data-testid="email-error">
            {errors.email}
          </div>
        )}
      </div>

      <div className="checkout-page__field">
        <TextField
          fullWidth
          data-testid="confirm-email-input"
          label={<span data-testid="confirm-email-label">Confirm email *</span>}
          value={form.confirmEmail}
          onChange={(e) => updateForm({ confirmEmail: e.target.value })}
          onBlur={() => blurField('confirmEmail')}
          error={touched.confirmEmail && !!errors.confirmEmail}
        />
        {touched.confirmEmail && errors.confirmEmail && (
          <div className="checkout-page__error" data-testid="confirm-email-error">
            {errors.confirmEmail}
          </div>
        )}
      </div>

      <div className="checkout-page__field">
        <TextField
          fullWidth
          data-testid="phone-input"
          label={<span data-testid="phone-label">Phone number</span>}
          value={form.phone}
          onChange={(e) => updateForm({ phone: e.target.value })}
          onBlur={() => blurField('phone')}
          error={touched.phone && !!errors.phone}
        />
        {touched.phone && errors.phone && (
          <div className="checkout-page__error" data-testid="phone-error">
            {errors.phone}
          </div>
        )}
      </div>

      <div className="checkout-page__field">
        <FormControlLabel
          control={
            <Checkbox
              data-testid="terms-checkbox"
              checked={form.terms}
              onChange={(e) => {
                updateForm({ terms: e.target.checked });
                setTouched((prev) => ({ ...prev, terms: true }));
              }}
            />
          }
          label={<span data-testid="terms-label">I accept the terms and conditions *</span>}
        />
        {touched.terms && errors.terms && (
          <div className="checkout-page__error" data-testid="terms-error">
            {errors.terms}
          </div>
        )}
      </div>

      <div className="checkout-page__actions">
        <Button
          data-testid="checkout-back-button"
          variant="outlined"
          onClick={() => navigate(`/screenings/${screeningId}/summary`)}
        >
          Back
        </Button>
        <Button data-testid="pay-button" variant="contained" disabled={submitting} onClick={handlePay}>
          {submitting ? 'Processing…' : `Pay ${total.toFixed(2)} PLN`}
        </Button>
      </div>
    </div>
  );
}

export default CheckoutPage;

import Button from '@mui/material/Button';
import { useNavigate } from 'react-router-dom';
import { useBooking } from '../../booking/BookingContext';

export function ConfirmationPage() {
  const { booking, clear } = useBooking();
  const navigate = useNavigate();
  const email = booking?.email ?? '';

  function handleContinue() {
    clear();
    navigate('/');
  }

  return (
    <div className="confirmation-page" style={{ maxWidth: 600, margin: '0 auto', padding: 24, textAlign: 'center' }}>
      <h1 data-testid="confirmation-heading">Payment successful</h1>
      <p data-testid="confirmation-message">Your tickets will be sent shortly to {email}</p>
      <Button data-testid="confirmation-continue-button" variant="contained" onClick={handleContinue}>
        Continue
      </Button>
    </div>
  );
}

export default ConfirmationPage;

