import { createContext, ReactNode, useContext, useEffect, useMemo, useState } from 'react';

export interface CheckoutFormValues {
  firstName: string;
  lastName: string;
  email: string;
  confirmEmail: string;
  phone: string;
  terms: boolean;
}

export interface Booking {
  screeningId: number;
  seats: string[];
  form: CheckoutFormValues;
  paid: boolean;
  email: string | null;
}

const STORAGE_KEY = 'cinescope.booking';

const EMPTY_FORM: CheckoutFormValues = {
  firstName: '',
  lastName: '',
  email: '',
  confirmEmail: '',
  phone: '',
  terms: false,
};

function createEmptyBooking(screeningId: number): Booking {
  return { screeningId, seats: [], form: { ...EMPTY_FORM }, paid: false, email: null };
}

function loadBooking(): Booking | null {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    return raw ? (JSON.parse(raw) as Booking) : null;
  } catch {
    return null;
  }
}

interface BookingContextValue {
  booking: Booking | null;
  startBooking: (screeningId: number) => void;
  setSeats: (seats: string[]) => void;
  updateForm: (partial: Partial<CheckoutFormValues>) => void;
  clear: () => void;
  markPaid: (email: string) => void;
}

const BookingContext = createContext<BookingContextValue | null>(null);

export function BookingProvider({ children }: { children: ReactNode }) {
  const [booking, setBooking] = useState<Booking | null>(() => loadBooking());

  useEffect(() => {
    if (booking) sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
    else sessionStorage.removeItem(STORAGE_KEY);
  }, [booking]);

  const value = useMemo<BookingContextValue>(
    () => ({
      booking,
      startBooking: (screeningId) => {
        setBooking((current) => {
          if (current && current.screeningId === screeningId && !current.paid) return current;
          return createEmptyBooking(screeningId);
        });
      },
      setSeats: (seats) => {
        setBooking((current) => (current ? { ...current, seats } : current));
      },
      updateForm: (partial) => {
        setBooking((current) => (current ? { ...current, form: { ...current.form, ...partial } } : current));
      },
      clear: () => setBooking(null),
      markPaid: (email) => {
        setBooking((current) => (current ? { ...current, paid: true, email } : current));
      },
    }),
    [booking],
  );

  return <BookingContext.Provider value={value}>{children}</BookingContext.Provider>;
}

export function useBooking(): BookingContextValue {
  const ctx = useContext(BookingContext);
  if (!ctx) throw new Error('useBooking must be used within BookingProvider');
  return ctx;
}

import Snackbar from '@mui/material/Snackbar';
import { createContext, ReactNode, useCallback, useContext, useEffect, useRef, useState } from 'react';

interface ToastContextValue {
  showToast: (message: string) => void;
}

const ToastContext = createContext<ToastContextValue | null>(null);

export function ToastProvider({ children }: { children: ReactNode }) {
  const [message, setMessage] = useState<string | null>(null);
  const timeoutRef = useRef<ReturnType<typeof setTimeout>>();

  const showToast = useCallback((next: string) => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setMessage(next);
    timeoutRef.current = setTimeout(() => setMessage(null), 4000);
  }, []);

  useEffect(
    () => () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    },
    [],
  );

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
      {message !== null && (
        <Snackbar
          open
          message={message}
          data-testid="toast"
          anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
        />
      )}
    </ToastContext.Provider>
  );
}

export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error('useToast must be used within ToastProvider');
  return ctx;
}

import { ReactNode, useState } from 'react';
import { Navigate, useParams } from 'react-router-dom';
import { useBooking } from '../booking/BookingContext';

export function RequireActiveBooking({ children }: { children: ReactNode }) {
  const { id } = useParams();
  const { booking } = useBooking();
  const [allowed] = useState(() => {
    const screeningId = Number(id);
    return !!booking && !booking.paid && booking.screeningId === screeningId && booking.seats.length > 0;
  });
  if (!allowed) return <Navigate to="/" replace />;
  return <>{children}</>;
}

export function RequirePaidBooking({ children }: { children: ReactNode }) {
  const { booking } = useBooking();
  const [allowed] = useState(() => !!booking && booking.paid);
  if (!allowed) return <Navigate to="/" replace />;
  return <>{children}</>;
}

import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import Button from '@mui/material/Button';
import dayjs, { Dayjs } from 'dayjs';
import { addDaysIso, todayIso, weekdayFull } from '../../utils/date';

interface Props {
  selectedDate: string;
  onSelect: (date: string) => void;
}

export function DayPicker({ selectedDate, onSelect }: Props) {
  const today = todayIso();
  const days = Array.from({ length: 5 }, (_, i) => addDaysIso(today, i));
  const isPreset = days.includes(selectedDate);
  const datePickerValue: Dayjs | null = isPreset ? null : dayjs(selectedDate);

  function handleDatePickerChange(value: Dayjs | null) {
    if (value && value.isValid()) {
      onSelect(value.format('YYYY-MM-DD'));
    }
  }

  return (
    <div className="day-picker" data-testid="day-picker">
      {days.map((date, index) => (
        <Button
          key={date}
          data-testid="day-button"
          data-date={date}
          data-selected={selectedDate === date ? 'true' : 'false'}
          variant={selectedDate === date ? 'contained' : 'outlined'}
          onClick={() => onSelect(date)}
        >
          {index === 0 ? 'Today' : weekdayFull(date)}
        </Button>
      ))}
      <DatePicker
        label="Choose a date"
        value={datePickerValue}
        minDate={dayjs(today)}
        onChange={handleDatePickerChange}
        slotProps={{ textField: { 'data-testid': 'date-picker' } as never }}
      />
    </div>
  );
}

