export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

export interface ReservationCustomer {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
}

export interface ReservationInput {
  screeningId: number;
  seats: string[];
  customer: ReservationCustomer;
  totalPrice: number;
}

export interface Reservation extends ReservationInput {
  id: number;
}

import { Movie, Reservation, ReservationInput, Screening } from './types';

const BASE_URL = 'http://localhost:3000';

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`${BASE_URL}${path}`, init);
  if (!response.ok) {
    throw new Error(`Request to ${path} failed with status ${response.status}`);
  }
  return response.json() as Promise<T>;
}

export function fetchMovies(): Promise<Movie[]> {
  return request<Movie[]>('/movies');
}

export function fetchMovie(id: number): Promise<Movie> {
  return request<Movie>(`/movies/${id}`);
}

export function fetchScreenings(params: { date?: string; movieId?: number } = {}): Promise<Screening[]> {
  const search = new URLSearchParams();
  if (params.date) search.set('date', params.date);
  if (params.movieId !== undefined) search.set('movieId', String(params.movieId));
  const query = search.toString();
  return request<Screening[]>(`/screenings${query ? `?${query}` : ''}`);
}

export function fetchScreening(id: number): Promise<Screening> {
  return request<Screening>(`/screenings/${id}`);
}

export function createReservation(payload: ReservationInput): Promise<Reservation> {
  return request<Reservation>('/reservations', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });
}

export function formatIso(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

export function todayIso(): string {
  return formatIso(new Date());
}

export function addDaysIso(iso: string, days: number): string {
  const [year, month, day] = iso.split('-').map(Number);
  return formatIso(new Date(year, month - 1, day + days));
}

export function isValidIsoDate(value: string): boolean {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(year, month - 1, day);
  return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day;
}

export function resolveSelectedDate(param: string | null): string {
  const today = todayIso();
  if (!param) return today;
  if (!isValidIsoDate(param)) return today;
  if (param < today) return today;
  return param;
}

export function weekdayFull(iso: string): string {
  const [year, month, day] = iso.split('-').map(Number);
  return new Date(year, month - 1, day).toLocaleDateString('en-US', { weekday: 'long' });
}

export function formatShowDate(iso: string, time: string): string {
  const [year, month, day] = iso.split('-').map(Number);
  const date = new Date(year, month - 1, day);
  const weekday = date.toLocaleDateString('en-US', { weekday: 'long' });
  const monthShort = date.toLocaleDateString('en-US', { month: 'short' });
  return `${weekday} ${day} ${monthShort} ${time}`;
}

export interface SeatModel {
  kind: 'seat';
  row: number;
  column: number;
  accessible: boolean;
}

export interface CouchModel {
  kind: 'couch';
  row: number;
  columnStart: number;
  columnEnd: number;
}

export type AuditoriumItem = SeatModel | CouchModel;

export interface AuditoriumRow {
  row: number;
  items: AuditoriumItem[];
}

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function parseSeatId(id: string): { row: number; column: number } {
  const match = /^R(\d+)C(\d+)$/.exec(id);
  if (!match) throw new Error(`Invalid seat id: ${id}`);
  return { row: Number(match[1]), column: Number(match[2]) };
}

export function isAccessibleSeat(row: number, column: number): boolean {
  return row === 1 && column >= 10 && column <= 15;
}

export function buildAuditorium(): AuditoriumRow[] {
  const rows: AuditoriumRow[] = [];
  for (let row = 1; row <= 14; row++) {
    const startColumn = row <= 10 ? 5 : 1;
    const items: AuditoriumItem[] = [];
    for (let column = startColumn; column <= 24; column++) {
      items.push({ kind: 'seat', row, column, accessible: isAccessibleSeat(row, column) });
    }
    rows.push({ row, items });
  }
  const couchItems: AuditoriumItem[] = [];
  for (let columnStart = 1; columnStart <= 23; columnStart += 2) {
    couchItems.push({ kind: 'couch', row: 15, columnStart, columnEnd: columnStart + 1 });
  }
  rows.push({ row: 15, items: couchItems });
  return rows;
}

export interface SelectionSeatItem {
  row: number;
  kind: 'seat';
  column: number;
}

export interface SelectionCouchItem {
  row: number;
  kind: 'couch';
  columnStart: number;
  columnEnd: number;
}

export type SelectionItem = SelectionSeatItem | SelectionCouchItem;

export function groupSeatIds(ids: string[]): SelectionItem[] {
  const byRow = new Map<number, number[]>();
  for (const id of ids) {
    const { row, column } = parseSeatId(id);
    const columns = byRow.get(row) ?? [];
    columns.push(column);
    byRow.set(row, columns);
  }
  const rows = [...byRow.keys()].sort((a, b) => a - b);
  const items: SelectionItem[] = [];
  for (const row of rows) {
    const columns = [...(byRow.get(row) ?? [])].sort((a, b) => a - b);
    if (row === 15) {
      for (let i = 0; i < columns.length; i += 2) {
        items.push({ row, kind: 'couch', columnStart: columns[i], columnEnd: columns[i + 1] });
      }
    } else {
      for (const column of columns) items.push({ row, kind: 'seat', column });
    }
  }
  return items;
}

export function seatIdsForItem(item: SelectionItem): string[] {
  return item.kind === 'seat'
    ? [seatId(item.row, item.column)]
    : [seatId(item.row, item.columnStart), seatId(item.row, item.columnEnd)];
}

export function flattenItemsToIds(items: SelectionItem[]): string[] {
  return items.flatMap(seatIdsForItem);
}

import { SelectionItem } from './seats';

export const COUCH_PRICE = 89;

export function priceForRow(row: number): number {
  if (row <= 5) return 25;
  if (row <= 10) return 32;
  return 39;
}

export function priceForItem(item: SelectionItem): number {
  return item.kind === 'couch' ? COUCH_PRICE : priceForRow(item.row);
}

export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

export const SEAT_COLORS: Record<SeatState, string> = {
  available: '#2E7D32',
  selected: '#F9A825',
  unavailable: '#C62828',
  accessible: '#1565C0',
};

export const SEAT_STATE_LABELS: Record<SeatState, string> = {
  available: 'Available',
  selected: 'Selected',
  unavailable: 'Unavailable',
  accessible: 'Accessible',
};

import { createContext, ReactNode, useContext, useEffect, useMemo, useState } from 'react';

export interface CheckoutFormValues {
  firstName: string;
  lastName: string;
  email: string;
  confirmEmail: string;
  phone: string;
  terms: boolean;
}

export interface Booking {
  screeningId: number;
  seats: string[];
  form: CheckoutFormValues;
  paid: boolean;
  email: string | null;
}

const STORAGE_KEY = 'cinescope.booking';

const EMPTY_FORM: CheckoutFormValues = {
  firstName: '',
  lastName: '',
  email: '',
  confirmEmail: '',
  phone: '',
  terms: false,
};

function createEmptyBooking(screeningId: number): Booking {
  return { screeningId, seats: [], form: { ...EMPTY_FORM }, paid: false, email: null };
}

function loadBooking(): Booking | null {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    return raw ? (JSON.parse(raw) as Booking) : null;
  } catch {
    return null;
  }
}

interface BookingContextValue {
  booking: Booking | null;
  startBooking: (screeningId: number) => void;
  setSeats: (seats: string[]) => void;
  updateForm: (partial: Partial<CheckoutFormValues>) => void;
  clear: () => void;
  markPaid: (email: string) => void;
}

const BookingContext = createContext<BookingContextValue | null>(null);

export function BookingProvider({ children }: { children: ReactNode }) {
  const [booking, setBooking] = useState<Booking | null>(() => loadBooking());

  useEffect(() => {
    if (booking) sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
    else sessionStorage.removeItem(STORAGE_KEY);
  }, [booking]);

  const value = useMemo<BookingContextValue>(
    () => ({
      booking,
      startBooking: (screeningId) => {
        setBooking((current) => {
          if (current && current.screeningId === screeningId && !current.paid) return current;
          return createEmptyBooking(screeningId);
        });
      },
      setSeats: (seats) => {
        setBooking((current) => (current ? { ...current, seats } : current));
      },
      updateForm: (partial) => {
        setBooking((current) => (current ? { ...current, form: { ...current.form, ...partial } } : current));
      },
      clear: () => setBooking(null),
      markPaid: (email) => {
        setBooking((current) => (current ? { ...current, paid: true, email } : current));
      },
    }),
    [booking],
  );

  return <BookingContext.Provider value={value}>{children}</BookingContext.Provider>;
}

export function useBooking(): BookingContextValue {
  const ctx = useContext(BookingContext);
  if (!ctx) throw new Error('useBooking must be used within BookingProvider');
  return ctx;
}

import Snackbar from '@mui/material/Snackbar';
import { createContext, ReactNode, useCallback, useContext, useEffect, useRef, useState } from 'react';

interface ToastContextValue {
  showToast: (message: string) => void;
}

const ToastContext = createContext<ToastContextValue | null>(null);

export function ToastProvider({ children }: { children: ReactNode }) {
  const [message, setMessage] = useState<string | null>(null);
  const timeoutRef = useRef<ReturnType<typeof setTimeout>>();

  const showToast = useCallback((next: string) => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setMessage(next);
    timeoutRef.current = setTimeout(() => setMessage(null), 4000);
  }, []);

  useEffect(
    () => () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    },
    [],
  );

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
      {message !== null && (
        <Snackbar
          open
          message={message}
          data-testid="toast"
          anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
        />
      )}
    </ToastContext.Provider>
  );
}

export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error('useToast must be used within ToastProvider');
  return ctx;
}

import { ReactNode, useState } from 'react';
import { Navigate, useParams } from 'react-router-dom';
import { useBooking } from '../booking/BookingContext';

export function RequireActiveBooking({ children }: { children: ReactNode }) {
  const { id } = useParams();
  const { booking } = useBooking();
  const [allowed] = useState(() => {
    const screeningId = Number(id);
    return !!booking && !booking.paid && booking.screeningId === screeningId && booking.seats.length > 0;
  });
  if (!allowed) return <Navigate to="/" replace />;
  return <>{children}</>;
}

export function RequirePaidBooking({ children }: { children: ReactNode }) {
  const { booking } = useBooking();
  const [allowed] = useState(() => !!booking && booking.paid);
  if (!allowed) return <Navigate to="/" replace />;
  return <>{children}</>;
}

import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import Button from '@mui/material/Button';
import dayjs, { Dayjs } from 'dayjs';
import { addDaysIso, todayIso, weekdayFull } from '../../utils/date';

interface Props {
  selectedDate: string;
  onSelect: (date: string) => void;
}

export function DayPicker({ selectedDate, onSelect }: Props) {
  const today = todayIso();
  const days = Array.from({ length: 5 }, (_, i) => addDaysIso(today, i));
  const isPreset = days.includes(selectedDate);
  const datePickerValue: Dayjs | null = isPreset ? null : dayjs(selectedDate);

  function handleDatePickerChange(value: Dayjs | null) {
    if (value && value.isValid()) {
      onSelect(value.format('YYYY-MM-DD'));
    }
  }

  return (
    <div className="day-picker" data-testid="day-picker">
      {days.map((date, index) => (
        <Button
          key={date}
          data-testid="day-button"
          data-date={date}
          data-selected={selectedDate === date ? 'true' : 'false'}
          variant={selectedDate === date ? 'contained' : 'outlined'}
          onClick={() => onSelect(date)}
        >
          {index === 0 ? 'Today' : weekdayFull(date)}
        </Button>
      ))}
      <DatePicker
        label="Choose a date"
        value={datePickerValue}
        minDate={dayjs(today)}
        onChange={handleDatePickerChange}
        slotProps={{ textField: { 'data-testid': 'date-picker' } as never }}
      />
    </div>
  );
}

export default DayPicker;

